            byte[] nullableLayers=root("{\"layers\":null,\"futureCanopy\":9007199254740993}");check(ProceduralCanopies.layers(row(nullableLayers))==null && ProceduralCanopies.layers(row(ProceduralCanopies.changeLayers(path,nullableLayers,owner,RiverProfiles.Action.ADD,-1))).size()==1 && object(ProceduralCanopies.resetLayers(path,nullableLayers,owner),canopy).token("layers")==null);
            byte[] exactLayers=root("{\"layers\":[{\"yOffset\":7e0,\"radius\":2e0,\"futureLayer\":9007199254740993},{\"yOffset\":-3,\"radius\":4}],\"futureCanopy\":9223372036854775807,\"branches\":{\"subBranches\":{\"count\":2},\"futureBranches\":true}}");byte[] copy=ProceduralCanopies.changeLayers(path,exactLayers,owner,RiverProfiles.Action.DUPLICATE,0);check(Arrays.equals(ProceduralCanopies.layers(row(copy)).get(0).sourceBytes(),ProceduralCanopies.layers(row(copy)).get(1).sourceBytes()));
